import json,pathlib,html
R=pathlib.Path(__file__).resolve().parent;s=json.loads((R/'summary.json').read_text())
rows=''
for key,title,caption in [('fresh','Fresh set · primary','120 new texts'),('round1_rerun','Round-1 set · current engine','120 unchanged texts, newly checked')]:
 q=s[key]['quality'];bars=''
 for k,label,cls in [('ours','Ours',''),('zerogpt','ZeroGPT',' zero')]:
  v=q[k];bars+=f'<div class="bar{cls}" tabindex="0" title="{label}: {v:.4f} out of 10" style="--value:{v*10:.6f}%"><i class="mark"></i><span>{label} <strong>{v:.1f}</strong><small> / 10</small></span></div>'
 rows+=f'<div class="row"><div><h4>{title}</h4><p>{caption}</p></div><div class="pair">{bars}</div></div>'
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Round Two Comparison</title>
<style>
/* Two matched score groups; zero-based 0–10 scale, with exact counts in the table. */
:root{--surface:#fcfcfb;--ink:#0b0b0b;--secondary-ink:#52514e;--s1:#2a78d6;--s2:#eb6834;--grid:#e1e0d9;--font-display:var(--font-sans,system-ui);--font-body:var(--font-sans,system-ui);--font-data:var(--font-mono,monospace)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--surface:#1a1a19;--ink:#f0efec;--secondary-ink:#c3c2b7;--s1:#3987e5;--s2:#d95926;--grid:#383835;color-scheme:dark}}
:root[data-theme="dark"]{--surface:#1a1a19;--ink:#f0efec;--secondary-ink:#c3c2b7;--s1:#3987e5;--s2:#d95926;--grid:#383835;color-scheme:dark}
*{box-sizing:border-box}section{color:var(--ink);font:14px/1.5 var(--font-body);display:grid;gap:18px;min-width:0}h3,h4,p{margin:0}h3{font:600 17px var(--font-display)}h4{font-size:14px}p,small,.axis{color:var(--secondary-ink)}.legend{display:flex;gap:24px}.swatch{display:inline-block;width:10px;height:10px;margin-right:6px;background:var(--s1)}.swatch.zero{background:var(--s2)}.row{display:grid;grid-template-columns:minmax(130px,1fr) minmax(120px,1.7fr);gap:16px;align-items:center}.row p{font-size:12px}.pair{display:grid;gap:6px}.bar{position:relative;height:36px;border-left:1px solid var(--grid);padding-left:5px;display:flex;align-items:flex-end;font-size:13px}.mark{position:absolute;left:0;top:0;height:10px;border-radius:0 4px 4px 0;background:var(--s1);width:var(--value)}.zero .mark{background:var(--s2)}.bar:focus{outline:2px solid var(--ring,var(--s1));outline-offset:2px}.axis{display:flex;justify-content:space-between;font:11px var(--font-data);margin-bottom:4px}.axis-grid{background:linear-gradient(to right,var(--grid) 1px,transparent 1px);background-size:20% 100%;height:5px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:left;padding:6px 8px;border-bottom:1px solid var(--grid);font-variant-numeric:tabular-nums}summary{cursor:pointer}small{font-size:12px}.note{font-size:12px;max-width:68ch}.textures .zero .mark{background-image:repeating-linear-gradient(135deg,transparent 0 3px,var(--ink) 3px 4px)}button{font:inherit;color:var(--ink);background:var(--surface);border:1px solid var(--grid);border-radius:4px;padding:4px 8px;cursor:pointer}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:center;justify-content:space-between}
@media(max-width:430px){.row{grid-template-columns:1fr;gap:8px}}@media print,(forced-colors:active){.zero .mark{background-image:repeating-linear-gradient(135deg,transparent 0 3px,var(--ink) 3px 4px)}}
</style></head><body><section id="scores" aria-label="Final round two quality-score comparison"><h3>Final quality scores</h3><div class="controls"><div class="legend"><span><i class="swatch"></i>Ours</span><span><i class="swatch zero"></i>ZeroGPT</span></div><button id="texture-toggle" type="button" aria-pressed="false" onclick="const s=document.getElementById('scores');s.classList.toggle('textures');this.setAttribute('aria-pressed',s.classList.contains('textures'))">Toggle texture</button></div>
'''+rows+'''<div class="row"><div aria-hidden="true"></div><div><div class="axis"><span>0</span><span>Quality score · higher is better</span><span>10</span></div><div class="axis-grid"></div></div></div><p class="note">Same fixed formula for both: 40% human specificity + 20% raw-AI sensitivity + 40% hard-AI sensitivity, multiplied by 10. Polishing excluded. The round-1 rerun is not unseen validation.</p><details><summary>Exact score components</summary><div class="table-wrap"><table><thead><tr><th>Set / detector</th><th>Humans correct</th><th>Raw caught</th><th>Hard caught</th></tr></thead><tbody><tr><td>Fresh / ours</td><td>59/60</td><td>20/20</td><td>26/30</td></tr><tr><td>Fresh / ZeroGPT</td><td>59/60</td><td>20/20</td><td>29/30</td></tr><tr><td>Round 1 / ours</td><td>59/60</td><td>20/20</td><td>28/30</td></tr><tr><td>Round 1 / ZeroGPT</td><td>60/60</td><td>20/20</td><td>30/30</td></tr></tbody></table></div></details></section></body></html>'''
(R/'comparison.html').write_text(page)
print('Wrote comparison.html')
